import { describe, expect, it } from "vitest";
import {
  ClientMethods,
  VIEW_SCHEMAS,
  isGameResults,
  isLobbyState,
  isRoomPeek,
  parseControllerView,
  type ChoiceInput,
  type ControllerView,
  type CustomInput,
  type JoinResult,
  type LobbyState,
  type RoomPeek,
} from "../src/protocol";

// Generated by src/ArcBox.Sdk.Tests/ContractFixtureTests.cs from the real C# serializer.
const fixtures = import.meta.glob<{ default: unknown }>("./fixtures/*.json", { eager: true });
const fixture = (name: string) => {
  const mod = fixtures[`./fixtures/${name}.json`];
  if (!mod) throw new Error(`missing fixture ${name}`);
  return structuredClone(mod.default) as Record<string, unknown>;
};

const viewKinds = ["wait", "textEntry", "choice", "buttons", "draw", "shake", "custom"] as const;

describe("contract fixtures", () => {
  it("has a fixture for every view kind plus lobby, results and the choice input", () => {
    const names = Object.keys(fixtures).map((k) => k.replace("./fixtures/", "").replace(".json", "")).sort();
    expect(names).toEqual([...viewKinds, "choiceInput", "customInput", "peek", "takeSeat", "lobbyCampaign", "lobby", "results"].sort());
  });

  it.each(viewKinds)("parseControllerView accepts %s with every schema field typed", (kind) => {
    const json = fixture(kind);
    const view: ControllerView = parseControllerView(json);
    expect(view.kind).toBe(kind);
    expect(view.viewId).toBe("v1");
    expect(view.header).toBe("H");
    expect(typeof view.deadlineUtc).toBe("string");
    expect(Number.isNaN(Date.parse(view.deadlineUtc!))).toBe(false);

    // Both directions: the schema names every field the server sends, and every schema field is present here.
    const schema = VIEW_SCHEMAS[kind];
    expect(Object.keys(json).sort()).toEqual(Object.keys(schema).sort());
  });

  it("choice fixture keeps option hints and omits a missing one", () => {
    const view = parseControllerView(fixture("choice"));
    if (view.kind !== "choice") throw new Error("expected choice");
    expect(view.options[0]).toEqual({ id: "PIA", label: "#81 Oscar Piastri", hint: "McLaren · MCL40" });
    expect("hint" in view.options[2]!).toBe(false);
    expect(view.allowMultiple).toBe(false);
    expect(view.maxSelections).toBe(1);
  });

  it("buttons, textEntry and draw carry their typed fields", () => {
    const buttons = parseControllerView(fixture("buttons"));
    if (buttons.kind !== "buttons") throw new Error("expected buttons");
    expect(buttons.buttons.map((b) => b.id)).toEqual(["cruise", "push", "redline"]);
    const text = parseControllerView(fixture("textEntry"));
    if (text.kind !== "textEntry") throw new Error("expected textEntry");
    expect(text.maxLength).toBe(40);
    expect(text.placeholder).toBe("type here");
    const draw = parseControllerView(fixture("draw"));
    if (draw.kind !== "draw") throw new Error("expected draw");
    expect(draw.colors).toEqual(["#111111", "#e10600"]);
  });

  it("shake carries prompt, colour, canFire and initialCharge", () => {
    const view = parseControllerView(fixture("shake"));
    if (view.kind !== "shake") throw new Error("expected shake");
    expect(view.prompt).toBe("Pop the cork! Shake again to reload");
    expect(view.color).toBe("#ff8000");
    expect(view.canFire).toBe(true);
    expect(view.initialCharge).toBe(0.35);
    // Colour is optional; the other fields are not.
    expect(parseControllerView({ ...fixture("shake"), color: null }).kind).toBe("shake");
    expect(() => parseControllerView({ ...fixture("shake"), canFire: "yes" })).toThrow(/canFire/);
    expect(() => parseControllerView({ ...fixture("shake"), initialCharge: undefined })).toThrow(/initialCharge/);
  });

  it("custom carries module, screen and untouched data", () => {
    const view = parseControllerView(fixture("custom"));
    if (view.kind !== "custom") throw new Error("expected custom");
    expect(view.module).toBe("tactics");
    expect(view.screen).toBe("targetPicker");
    expect(view.data).toEqual({ cursor: { x: 2, y: 3 }, targets: [{ id: "orc1", hit: 75 }] });
    expect(() => parseControllerView({ ...fixture("custom"), module: 1 })).toThrow(/module/);
    expect(() => parseControllerView({ ...fixture("custom"), screen: undefined })).toThrow(/screen/);
    // data is any JSON value, but it must be there.
    expect(() => parseControllerView({ ...fixture("custom"), data: undefined })).toThrow(/data/);
    expect(parseControllerView({ ...fixture("custom"), data: null }).kind).toBe("custom");
  });

  it("customInput fixture parses as a CustomInput", () => {
    const input = fixture("customInput") as unknown as CustomInput;
    expect(input.action).toBe("target");
    expect(input.data).toEqual({ id: "orc1" });
    expect(Object.keys(input).sort()).toEqual(["action", "data"]);
  });

  it("peek fixture is a RoomPeek with member and slot offers and a suggestion", () => {
    const peek = fixture("peek") as unknown as RoomPeek;
    expect(Object.keys(peek).sort()).toEqual(["campaignName", "canJoinNew", "code", "gameId", "inGame", "offers", "suggested"]);
    expect(peek.campaignName).toBe("Embers of the Vale");
    expect(peek.offers).toHaveLength(2);
    expect(peek.offers[0]!.ref).toEqual({ slot: null, member: "pr_AbCdEfGhIjKlMnOp" });
    expect(peek.offers[0]!.card.subtitle).toBe("Dwarf Cleric · Lv 3");
    expect(peek.offers[1]!.ref).toEqual({ slot: "p3", member: null });
    expect(peek.offers[1]!.absent).toBe(true);
    expect(peek.offers[1]!.card).toEqual({ title: "Mira", subtitle: null, color: null, portrait: null });
    expect(peek.suggested?.ref.member).toBe("pr_AbCdEfGhIjKlMnOp");
    expect(peek.canJoinNew).toBe(true);
    expect(isRoomPeek(fixture("peek"))).toBe(true); // the phone's runtime check accepts what the real serializer writes
  });

  it("takeSeat fixture is a JoinResult with a profile key", () => {
    const result = fixture("takeSeat") as unknown as JoinResult;
    expect(Object.keys(result).sort()).toEqual(["code", "playerId", "profile", "secret"]);
    expect(result.profile).toEqual({ id: "pr_AbCdEfGhIjKlMnOp", key: "a2V5LWtleS1rZXk", name: "Dave" });
  });

  it("lobbyCampaign fixture is a LobbyState with a campaign, a campaign list and a player profile", () => {
    const json = fixture("lobbyCampaign");
    expect(isLobbyState(json)).toBe(true);
    const lobby = json as unknown as LobbyState;
    expect(lobby.players[0]!.profile).toBe("pr_AbCdEfGhIjKlMnOp");
    expect(lobby.games[0]).toMatchObject({ usesCampaigns: true, resumesAfterRestart: true });
    expect(lobby.campaign?.code).toBe("KQZT");
    expect(lobby.campaign?.roster).toHaveLength(2);
    expect(lobby.campaign?.roster[0]).toEqual({
      profile: "pr_AbCdEfGhIjKlMnOp",
      card: { title: "Aldric", subtitle: "Dwarf Cleric · Lv 3", color: null, portrait: null },
      seatedAs: "p1",
      connected: true,
    });
    expect(lobby.campaign?.roster[1]!.seatedAs).toBeNull();
    expect(lobby.campaigns).toEqual([{ id: "c1", code: "KQZT", name: "Embers of the Vale", members: 2, updatedUtc: "2026-01-01T00:00:00+00:00" }]);
    expect(isLobbyState({ ...json, campaign: { id: "c1" } })).toBe(false);
  });

  it("an unknown kind throws", () => {
    expect(() => parseControllerView({ ...fixture("wait"), kind: "nope" })).toThrow(/nope/);
  });

  it("a field with the wrong type throws", () => {
    expect(() => parseControllerView({ ...fixture("textEntry"), maxLength: "40" })).toThrow(/maxLength/);
    expect(() => parseControllerView({ ...fixture("choice"), options: [{ id: 1, label: "x" }] })).toThrow(/options/);
  });

  it("choiceInput fixture parses as a ChoiceInput with elapsedMs", () => {
    const input = fixture("choiceInput") as unknown as ChoiceInput;
    expect(input.selected).toEqual(["b"]);
    expect(input.elapsedMs).toBe(2410.5);
    expect(Object.keys(input).sort()).toEqual(["elapsedMs", "selected"]);
  });

  it("lobby fixture is a LobbyState", () => {
    const json = fixture("lobby");
    expect(isLobbyState(json)).toBe(true);
    expect(Object.keys(json).sort()).toEqual(
      ["code", "players", "selectedGameId", "games", "inGame", "canStart", "lastResults"].sort(),
    );
    // The campaign additions are omitted for games that don't use campaigns.
    expect(json).not.toHaveProperty("campaign");
    expect(json).not.toHaveProperty("campaigns");
    const players = json.players as Record<string, unknown>[];
    expect(Object.keys(players[0]!).sort()).toEqual(["id", "name", "isVip", "connected"].sort());
    const games = json.games as Record<string, unknown>[];
    expect(Object.keys(games[0]!).sort()).toEqual(
      ["id", "name", "description", "minPlayers", "maxPlayers", "usesCampaigns", "resumesAfterRestart"].sort(),
    );
    expect(isLobbyState({ ...json, players: [{ id: "p1" }] })).toBe(false);
  });

  it("results fixture is a GameResults", () => {
    const json = fixture("results");
    expect(isGameResults(json)).toBe(true);
    expect(Object.keys(json).sort()).toEqual(["message", "scores"]);
    const score = (json.scores as Record<string, unknown>[])[0]!;
    expect(Object.keys(score).sort()).toEqual(["name", "playerId", "score"]);
    expect(isGameResults({ scores: [{ playerId: "p1", name: "A", score: "1" }] })).toBe(false);
  });

  it("client method names match ClientMethods.cs", () => {
    expect(ClientMethods).toEqual({
      LobbyChanged: "LobbyChanged",
      HostView: "HostView",
      ControllerView: "ControllerView",
      GameEnded: "GameEnded",
      RoomClosed: "RoomClosed",
      Kicked: "Kicked",
      ContentRequired: "ContentRequired",
    });
  });
});

describe("manifest leniency (a stale server or phone must not break lobby parsing)", () => {
  const withGames = (games: unknown[]) => ({ ...fixture("lobby"), games });
  const manifest = { id: "counter", name: "Counter", description: "Tap", minPlayers: 1, maxPlayers: 8 };

  it("accepts a manifest that predates usesCampaigns and resumesAfterRestart", () => {
    expect(isLobbyState(withGames([manifest]))).toBe(true);
    expect(isLobbyState(withGames([{ ...manifest, usesCampaigns: true }]))).toBe(true);
    expect(isLobbyState(withGames([{ ...manifest, resumesAfterRestart: false }]))).toBe(true);
  });

  it("rejects a manifest whose flags are present but not booleans", () => {
    expect(isLobbyState(withGames([{ ...manifest, usesCampaigns: "yes" }]))).toBe(false);
    expect(isLobbyState(withGames([{ ...manifest, resumesAfterRestart: 1 }]))).toBe(false);
  });
});

